//! OpenGL entry points for the Windows simulator.
//!
//! The app and the vendored plx crates call GL through plain `extern "C"` declarations, which on
//! the TV resolve against libGLESv2. Windows' opengl32.dll exports only GL 1.1, so every name in
//! `gl_names.txt` is defined here as a tiny exported trampoline (`jmp [table + 8*i]`, generated by
//! build.rs) and the table is filled from `SDL_GL_GetProcAddress` once the context exists. The
//! trampolines forward any signature unchanged, so no prototypes are restated.

use std::ffi::CString;
use std::os::raw::{c_char, c_void};

include!(concat!(env!("OUT_DIR"), "/gl_shim.rs"));

extern "C" {
    fn SDL_GL_GetProcAddress(name: *const c_char) -> *mut c_void;
}

/// Target of every entry the driver does not provide: logs once per process and does nothing.
extern "C" fn missing() -> usize {
    static ONCE: std::sync::Once = std::sync::Once::new();
    ONCE.call_once(|| crate::log("sim gl: a GL entry point the driver lacks was called (ignored)"));
    0
}

/// Resolves every trampoline. Main thread, after `SDL_GL_CreateContext`.
pub fn load() {
    let mut absent = Vec::new();
    for (i, name) in GL_NAMES.iter().enumerate() {
        let c = CString::new(*name).unwrap();
        let p = unsafe { SDL_GL_GetProcAddress(c.as_ptr()) };
        let p = if p.is_null() {
            absent.push(*name);
            missing as *const () as usize
        } else {
            p as usize
        };
        unsafe { (*std::ptr::addr_of_mut!(YTSIM_GL_TABLE))[i] = p };
    }
    crate::log(&format!("sim gl: {} entry points resolved, missing: {absent:?}", GL_NAMES.len() - absent.len()));
}
